import { Component, OnDestroy, inject, signal } from '@angular/core';
import { DatePipe } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute, RouterLink } from '@angular/router';
import { EMPTY, Subject, Subscription, catchError, concatMap, debounceTime, finalize, forkJoin, of, tap, throwError } from 'rxjs';
import { AcademicAgreement, AcademicDimension, AcademicEvaluationReconciliation, AcademicLimitationAnalysis, AcademicLimitationCategory, AcademicPeerEvaluation, AcademicReportEvaluation, AssessmentStudy, ManualReport, PersonalAssessmentCollection, PersonalAssessmentReport, PersonalAssessmentService, PersonalAssessmentSummary, ReportDraft, ReportGenerationExecution } from './personal-assessment.service';

type SectionKey = keyof ReportDraft;
type TimingPhase = 'MANUAL'|'REVIEW';
type SaveRequest = { revision: number; draft: ReportDraft; conclusion: string; confirmed: boolean; reviewActiveMillis: number };

export class ActiveTimeTracker {
  private phase:TimingPhase|null=null; private lastTick:number|null=null; private lastActivity=0;
  private readonly totals:Record<TimingPhase,number>={MANUAL:0,REVIEW:0};
  constructor(private readonly now:()=>number=()=>performance.now(),private readonly visible:()=>boolean=()=>document.visibilityState==='visible'){}
  begin(phase:TimingPhase){const now=this.now();this.tickAt(now);this.phase=phase;this.lastTick=now;this.lastActivity=now}
  activity(phase:TimingPhase){const now=this.now();this.tickAt(now);if(this.phase!==phase){this.phase=phase;this.lastTick=now}this.lastActivity=now}
  end(phase:TimingPhase){if(this.phase!==phase)return;this.tickAt(this.now());this.phase=null}
  tick(){this.tickAt(this.now())}
  visibilityChanged(){const now=this.now();this.lastTick=now;if(this.visible())this.lastActivity=now}
  hydrate(phase:TimingPhase,value:number){this.totals[phase]=Math.max(this.totals[phase],value||0)}
  total(phase:TimingPhase){this.tick();return Math.round(this.totals[phase])}
  private tickAt(now:number){if(this.phase&&this.visible()&&this.lastTick!==null){const activeUntil=Math.min(now,this.lastActivity+30_000);if(activeUntil>this.lastTick)this.totals[this.phase]+=Math.min(activeUntil-this.lastTick,1_500)}this.lastTick=now}
}

@Component({
  selector: 'app-personal-assessment-report',
  imports: [FormsModule, RouterLink, DatePipe],
  template: `<section class="page">
    <a [routerLink]="['/assessments',id]" class="back">← Voltar à avaliação</a>
    @if(loading()){<p class="state">Carregando parecer…</p>}
    @else if(loadError()){<p class="error" role="alert">{{loadError()}}</p>}
    @else if(assessment();as current){
      <header><div><p class="eyebrow">{{report()?.status==='APPROVED'?'PARECER APROVADO':'MINUTA DE PARECER'}}</p><h1>{{current.title}}</h1><span>{{current.personName}}</span></div>
      @if(report()&&report()?.status==='DRAFT'){<span class="save-state" [class.failed]="!!saveError()">{{saveLabel()}}</span>}</header>
      @if(!report()){
        <section class="empty-card"><h2>Gerar minuta com o Ollama local</h2><p>A minuta usa somente os registros desta avaliação. Ela deverá ser revisada e não contém a sua conclusão.</p>
        @if(actionError()){<p class="error" role="alert">{{actionError()}}</p>}
        <button type="button" (click)="generate()" [disabled]="working()||!collection()?.generationEligible||(study()&&!study()?.finalized)">{{working()?'Aguarde…':'Gerar minuta'}}</button>
        @if(!study()){<button type="button" class="secondary" (click)="startStudy()" [disabled]="working()">Iniciar comparação acadêmica</button>}</section>
        @if(study();as currentStudy){<section class="manual" (focusin)="beginTiming('MANUAL',$event)" (focusout)="endTiming('MANUAL',$event)" (input)="activityTiming('MANUAL',$event)" (keydown)="activityTiming('MANUAL',$event)"><p class="eyebrow">ARTEFATO DE CONTROLE</p><h2>Parecer elaborado manualmente</h2><p>Finalize este parecer antes de revelar a minuta. Seu conteúdo nunca será enviado ao Ollama.</p>
          @for(field of manualDefinitions;track field.key){<label>{{field.label}}<textarea [ngModel]="manualReport()[field.key]" (ngModelChange)="updateManual(field.key,$event)" [readonly]="currentStudy.finalized" rows="4"></textarea></label>}
          @if(currentStudy.finalized){<p class="success">Parecer manual congelado no contexto {{currentStudy.contextHash?.slice(0,12)}}…. Agora a minuta pode ser gerada.</p>}
          @else{<div class="manual-actions"><button type="button" class="secondary" (click)="saveManual()" [disabled]="working()||!manualDirty()">Salvar parecer manual</button><button type="button" (click)="finalizeManual()" [disabled]="working()||manualDirty()||!manualComplete()">Finalizar e congelar</button></div>}
          @if(currentStudy.timingVersion){<small class="timing">Tempo ativo de redação: {{formatDuration(manualActiveMillis())}}</small>}
        </section>}
      } @else if(report();as currentReport){
        @if(actionError()){<p class="error" role="alert">{{actionError()}}</p>}
        @if(saveError()){<p class="error save-error" role="alert"><span>{{saveError()}}</span><button type="button" (click)="retrySave()">Tentar novamente</button></p>}
        <p class="notice">{{currentReport.status==='APPROVED'?'Este é o parecer final aprovado e não pode mais ser alterado.':'Revise todas as seções. O conteúdo abaixo continua sendo uma minuta até sua aprovação.'}}</p>
        @if(study();as currentStudy){<section class="evaluation"><p class="eyebrow">FICHA ACADÊMICA</p><h2>Avaliação da minuta original</h2><p>Avalie a primeira saída do Ollama, antes das revisões. Esta ficha é humana e nunca é enviada ao modelo.</p>
          @for(item of dimensionDefinitions;track item.key;let index=$index){<article><div class="rating-head"><strong>{{item.label}}</strong><label>Nota<select [ngModel]="evaluation().dimensions[index].score" (ngModelChange)="updateRating(index,'score',$event)" [disabled]="currentStudy.evaluationFinalized"><option [ngValue]="null">Selecione</option><option [ngValue]="0">0</option><option [ngValue]="1">1</option><option [ngValue]="2">2</option></select></label></div><small>{{item.scale}}</small>
          <label>Justificativa<textarea [ngModel]="evaluation().dimensions[index].justification" (ngModelChange)="updateRating(index,'justification',$event)" [readonly]="currentStudy.evaluationFinalized" rows="3"></textarea></label>
          <div class="reference-grid"><label>Referências à entrada<textarea [ngModel]="joinReferences(evaluation().dimensions[index].sourceReferences)" (ngModelChange)="updateReferences(index,'sourceReferences',$event)" [readonly]="currentStudy.evaluationFinalized" rows="2" placeholder="Uma referência por linha, ex.: evidence-1"></textarea></label><label>Trechos/seções da minuta<textarea [ngModel]="joinReferences(evaluation().dimensions[index].draftReferences)" (ngModelChange)="updateReferences(index,'draftReferences',$event)" [readonly]="currentStudy.evaluationFinalized" rows="2" placeholder="Uma referência por linha, ex.: Pontos positivos, frase 2"></textarea></label></div></article>}
          <div class="counts"><label>Informações esperadas ausentes<input type="number" min="0" [ngModel]="evaluation().expectedInformationMissing" (ngModelChange)="updateCount('expectedInformationMissing',$event)" [readonly]="currentStudy.evaluationFinalized"></label><label>Afirmações factuais analisadas<input type="number" min="0" [ngModel]="evaluation().factualClaimsAnalyzed" (ngModelChange)="updateCount('factualClaimsAnalyzed',$event)" [readonly]="currentStudy.evaluationFinalized"></label><label>Afirmações sem sustentação<input type="number" min="0" [ngModel]="evaluation().unsupportedClaims" (ngModelChange)="updateCount('unsupportedClaims',$event)" [readonly]="currentStudy.evaluationFinalized"></label><label>Seções alteradas na revisão<input type="number" min="0" [ngModel]="evaluation().revisedSections" (ngModelChange)="updateCount('revisedSections',$event)" [readonly]="currentStudy.evaluationFinalized"></label></div>
          @if(currentStudy.evaluationFinalized){<p class="success">Ficha finalizada e congelada.</p><div class="manual-actions"><button type="button" class="secondary" (click)="exportAcademicSummary()" [disabled]="working()">Baixar resumo agregado (CSV)</button></div>
          <section class="peer-review"><h3>Revisão entre avaliadores</h3><p>Use um código pseudônimo para registrar fichas preenchidas de forma independente. O conteúdo não é enviado ao Ollama.</p>
            @if(!currentStudy.reconciliation){<div class="add-peer"><label>Código do avaliador<input type="text" maxlength="80" [ngModel]="peerReviewerCode()" (ngModelChange)="peerReviewerCode.set($event)" placeholder="Ex.: AV-B"></label><button type="button" class="secondary" (click)="createPeerEvaluation()" [disabled]="working()||peerReviewerCode().trim().length<2">Adicionar ficha independente</button></div>}
            @for(peer of peerEvaluations();track peer.id;let peerIndex=$index){<article><div class="rating-head"><strong>{{peer.reviewerCode}}</strong><span>{{peer.finalized?'Finalizada':'Em preenchimento'}}</span></div>
              @for(item of dimensionDefinitions;track item.key;let dimensionIndex=$index){<div class="peer-dimension"><div class="rating-head"><strong>{{item.label}}</strong><label>Nota<select [ngModel]="peer.evaluation.dimensions[dimensionIndex].score" (ngModelChange)="updatePeerRating(peerIndex,dimensionIndex,'score',$event)" [disabled]="peer.finalized"><option [ngValue]="null">Selecione</option><option [ngValue]="0">0</option><option [ngValue]="1">1</option><option [ngValue]="2">2</option></select></label></div>
                <label>Justificativa<textarea [ngModel]="peer.evaluation.dimensions[dimensionIndex].justification" (ngModelChange)="updatePeerRating(peerIndex,dimensionIndex,'justification',$event)" [readonly]="peer.finalized" rows="2"></textarea></label>
                <div class="reference-grid"><label>Referências à entrada<textarea [ngModel]="joinReferences(peer.evaluation.dimensions[dimensionIndex].sourceReferences)" (ngModelChange)="updatePeerReferences(peerIndex,dimensionIndex,'sourceReferences',$event)" [readonly]="peer.finalized" rows="2"></textarea></label><label>Referências à minuta<textarea [ngModel]="joinReferences(peer.evaluation.dimensions[dimensionIndex].draftReferences)" (ngModelChange)="updatePeerReferences(peerIndex,dimensionIndex,'draftReferences',$event)" [readonly]="peer.finalized" rows="2"></textarea></label></div></div>}
              <div class="counts"><label>Informações ausentes<input type="number" min="0" [ngModel]="peer.evaluation.expectedInformationMissing" (ngModelChange)="updatePeerCount(peerIndex,'expectedInformationMissing',$event)" [readonly]="peer.finalized"></label><label>Afirmações analisadas<input type="number" min="0" [ngModel]="peer.evaluation.factualClaimsAnalyzed" (ngModelChange)="updatePeerCount(peerIndex,'factualClaimsAnalyzed',$event)" [readonly]="peer.finalized"></label><label>Sem sustentação<input type="number" min="0" [ngModel]="peer.evaluation.unsupportedClaims" (ngModelChange)="updatePeerCount(peerIndex,'unsupportedClaims',$event)" [readonly]="peer.finalized"></label><label>Seções revisadas<input type="number" min="0" [ngModel]="peer.evaluation.revisedSections" (ngModelChange)="updatePeerCount(peerIndex,'revisedSections',$event)" [readonly]="peer.finalized"></label></div>
              @if(!peer.finalized){<div class="manual-actions"><button type="button" class="remove" (click)="deletePeerEvaluation(peer)" [disabled]="working()">Remover ficha</button><button type="button" class="secondary" (click)="savePeerEvaluation(peer)" [disabled]="working()||!peerDirty(peer.id)">Salvar ficha</button><button type="button" (click)="finalizePeerEvaluation(peer)" [disabled]="working()||peerDirty(peer.id)||!peerComplete(peer)">Finalizar ficha</button></div>}
            </article>}
            @if(agreement();as currentAgreement){<div class="agreement"><strong>Concordância exata: {{currentAgreement.exactAgreementPercent}}%</strong><span>{{currentAgreement.exactMatches}} de {{currentAgreement.ratingComparisons}} comparações · {{currentAgreement.evaluators}} avaliadores</span></div>}
            @if(peerSetReady()){<section class="reconciliation"><h4>Conciliação humana</h4>@for(item of dimensionDefinitions;track item.key;let index=$index){<div class="rating-head"><strong>{{item.label}}</strong><label>Nota conciliada<select [ngModel]="reconciliation().dimensions[index].agreedScore" (ngModelChange)="updateReconciliation(index,'agreedScore',$event)" [disabled]="currentStudy.reconciliationFinalized"><option [ngValue]="null">Selecione</option><option [ngValue]="0">0</option><option [ngValue]="1">1</option><option [ngValue]="2">2</option></select></label></div><label>Justificativa<textarea [ngModel]="reconciliation().dimensions[index].rationale" (ngModelChange)="updateReconciliation(index,'rationale',$event)" [readonly]="currentStudy.reconciliationFinalized" rows="2"></textarea></label>}
              <label>Conclusão da conciliação<textarea [ngModel]="reconciliation().overallConclusion" (ngModelChange)="updateReconciliationConclusion($event)" [readonly]="currentStudy.reconciliationFinalized" rows="3"></textarea></label>
              @if(currentStudy.reconciliationFinalized){<p class="success">Conciliação finalizada e congelada.</p>}@else{<div class="manual-actions"><button type="button" class="secondary" (click)="saveReconciliation()" [disabled]="working()||!reconciliationDirty()">Salvar conciliação</button><button type="button" (click)="finalizeReconciliation()" [disabled]="working()||reconciliationDirty()||!reconciliationComplete()">Finalizar conciliação</button></div>}
            </section>}
          </section>
          <section class="limitations"><h3>Limitações e ajustes</h3><p>Relacione cada limitação aos registros e à minuta. Esta análise é humana e nunca é enviada ao modelo.</p>
            @for(finding of limitationAnalysis().findings;track finding.id;let index=$index){<article><div class="rating-head"><strong>Limitação {{index+1}}</strong><label>Categoria<select [ngModel]="finding.category" (ngModelChange)="updateLimitation(index,'category',$event)" [disabled]="currentStudy.limitationAnalysisFinalized">@for(category of limitationCategories;track category.key){<option [value]="category.key">{{category.label}}</option>}</select></label></div>
              <label>Descrição<textarea [ngModel]="finding.description" (ngModelChange)="updateLimitation(index,'description',$event)" [readonly]="currentStudy.limitationAnalysisFinalized" rows="3"></textarea></label>
              <div class="reference-grid"><label>Referências à entrada<textarea [ngModel]="joinReferences(finding.sourceReferences)" (ngModelChange)="updateLimitationReferences(index,'sourceReferences',$event)" [readonly]="currentStudy.limitationAnalysisFinalized" rows="2"></textarea></label><label>Referências à minuta<textarea [ngModel]="joinReferences(finding.draftReferences)" (ngModelChange)="updateLimitationReferences(index,'draftReferences',$event)" [readonly]="currentStudy.limitationAnalysisFinalized" rows="2"></textarea></label></div>
              <label>Ajuste proposto<textarea [ngModel]="finding.proposedAdjustment" (ngModelChange)="updateLimitation(index,'proposedAdjustment',$event)" [readonly]="currentStudy.limitationAnalysisFinalized" rows="2"></textarea></label>
              <label>Impacto esperado<textarea [ngModel]="finding.expectedImpact" (ngModelChange)="updateLimitation(index,'expectedImpact',$event)" [readonly]="currentStudy.limitationAnalysisFinalized" rows="2"></textarea></label>
              <label>Plano de validação<textarea [ngModel]="finding.validationPlan" (ngModelChange)="updateLimitation(index,'validationPlan',$event)" [readonly]="currentStudy.limitationAnalysisFinalized" rows="2"></textarea></label>
              <label>Risco residual<textarea [ngModel]="finding.residualRisk" (ngModelChange)="updateLimitation(index,'residualRisk',$event)" [readonly]="currentStudy.limitationAnalysisFinalized" rows="2"></textarea></label>
              @if(!currentStudy.limitationAnalysisFinalized){<button type="button" class="remove" (click)="removeLimitation(index)">Remover limitação</button>}
            </article>}
            <label>Conclusão da análise<textarea [ngModel]="limitationAnalysis().overallConclusion" (ngModelChange)="updateLimitationConclusion($event)" [readonly]="currentStudy.limitationAnalysisFinalized" rows="3"></textarea></label>
            @if(currentStudy.limitationAnalysisFinalized){<p class="success">Análise de limitações finalizada e congelada.</p>}@else{<div class="manual-actions"><button type="button" class="secondary" (click)="addLimitation()">Adicionar limitação</button><button type="button" class="secondary" (click)="saveLimitationAnalysis()" [disabled]="working()||!limitationDirty()">Salvar análise</button><button type="button" (click)="finalizeLimitationAnalysis()" [disabled]="working()||limitationDirty()||!limitationAnalysisComplete()">Finalizar análise</button></div>}
          </section>
          @if(currentStudy.limitationAnalysisFinalized){<section class="experiment"><h3>Execuções de geração</h3><p>A minuta original permanece imutável. Uma nova execução usa exatamente o mesmo snapshot e testa um ajuste ligado a uma limitação finalizada.</p>
            @for(execution of generationExecutions();track execution.id){<details><summary>#{{execution.sequence}} · {{execution.kind==='ORIGINAL'?'Original':'Experimental'}} · {{execution.promptVersion}} · {{execution.model}}</summary><small>{{execution.createdAt|date:'short'}} · {{formatDuration(execution.generationLatencyMillis||0)}}</small>@if(execution.limitationReference){<p><strong>Limitação:</strong> {{execution.limitationReference}}</p>}@if(execution.justification){<p><strong>Justificativa:</strong> {{execution.justification}}</p>}@if(execution.kind==='EXPERIMENTAL'){@for(section of sectionDefinitions;track section.key){<h4>{{section.label}}</h4><p>{{execution.draft[section.key].text}}</p>}}</details>}
            <label>Limitação analisada<select [ngModel]="regenerationLimitationId()" (ngModelChange)="regenerationLimitationId.set($event)"><option value="">Selecione</option>@for(finding of limitationAnalysis().findings;track finding.id){<option [value]="finding.id">{{finding.category}} · {{finding.description}}</option>}</select></label>
            <label>Justificativa da nova execução<textarea [ngModel]="regenerationReason()" (ngModelChange)="regenerationReason.set($event)" rows="3" maxlength="2000" placeholder="Descreva o ajuste ou hipótese que será verificado."></textarea></label>
            <button type="button" (click)="regenerateExperimental()" [disabled]="working()||!regenerationLimitationId()||regenerationReason().trim().length<10">Gerar execução experimental</button>
          </section>}}@else{<div class="manual-actions"><button type="button" class="secondary" (click)="saveEvaluation()" [disabled]="working()||!evaluationDirty()">Salvar ficha</button><button type="button" (click)="finalizeEvaluation()" [disabled]="working()||evaluationDirty()||!evaluationComplete()">Finalizar ficha</button></div>}
        </section>}
        <div class="review-area" (focusin)="beginTiming('REVIEW',$event)" (focusout)="endTiming('REVIEW',$event)" (input)="activityTiming('REVIEW',$event)" (keydown)="activityTiming('REVIEW',$event)"><div class="sections">
          @for(section of sectionDefinitions;track section.key){<article><label>{{section.label}}<textarea [ngModel]="draft()?.[section.key]?.text" (ngModelChange)="updateSection(section.key,$event)" [readonly]="readOnly()" rows="6"></textarea></label>
          <small>@if(draft()?.[section.key]?.insufficientData){Dados insuficientes declarados · }{{draft()?.[section.key]?.evidenceReferences?.length||0}} referência(s) de evidência</small></article>}
        </div>
        <section class="conclusion"><label>Conclusão do entrevistador<textarea [ngModel]="humanConclusion()" (ngModelChange)="updateConclusion($event)" [readonly]="readOnly()" rows="7" placeholder="Escreva sua conclusão com base na avaliação e na revisão da minuta."></textarea></label><p>Esta conclusão é exclusivamente humana e nunca é enviada ao modelo.</p></section>
        @if(!readOnly()){
          <label class="confirmation"><input type="checkbox" [ngModel]="reviewConfirmed()" (ngModelChange)="updateConfirmation($event)"> Revisei a minuta e confirmo que o parecer final corresponde aos registros da avaliação.</label>
        } @if(study()?.timingVersion){<small class="timing">Tempo ativo de revisão: {{formatDuration(reviewActiveMillis())}} · Geração local: {{formatDuration(currentReport.generationLatencyMillis||0)}}</small>}</div>
        @if(!readOnly()){<footer><span>{{saveLabel()}}</span><button type="button" (click)="approve()" [disabled]="!canApprove()">{{working()?'Aprovando…':'Aprovar parecer'}}</button></footer>} @else {<div class="export"><button type="button" (click)="exportPdf()">Baixar parecer em PDF</button><span>O download não altera a aprovação.</span></div>}
      }
    }
  </section>`,
  styles: [`:host{display:block}.page{max-width:960px;margin:auto;padding:34px 24px 90px}.back{color:#176b66;text-decoration:none;font-size:12px;font-weight:800}header{display:flex;justify-content:space-between;gap:20px;margin:28px 0}header h1{margin:5px 0;font-size:33px}header span,.notice,.conclusion p,.manual>p,.evaluation>p,.limitations>p{color:#66767e}.eyebrow{margin:0;color:#278d83!important;font-size:10px;font-weight:900;letter-spacing:.14em}.save-state{align-self:start;padding:7px 11px;border-radius:14px;background:#e8f4ef;color:#23704d;font-size:11px;font-weight:800}.save-state.failed{background:#fff0ee;color:#a44035}.empty-card,.sections article,.conclusion,.manual,.evaluation{padding:22px;border:1px solid #dbe5e8;border-radius:12px;background:#fff}.empty-card button,footer button,.export button,.manual-actions button,.experiment>button,.add-peer button{padding:11px 15px;border:0;border-radius:8px;background:#176b66;color:#fff;font-weight:800}.secondary{margin-left:8px!important;border:1px solid #aacbc7!important;background:#fff!important;color:#176b66!important}.manual{display:grid;gap:13px;margin-top:16px}.manual h2,.evaluation h2{margin:0}.manual>p,.evaluation>p{margin:0}.manual-actions{display:flex;justify-content:flex-end;gap:8px}.manual-actions .secondary{margin-left:0!important}.success{padding:12px;border-radius:8px;background:#e8f4ef;color:#23704d!important}.evaluation{display:grid;gap:14px;margin:16px 0}.evaluation article{display:grid;gap:10px;padding:15px;border:1px solid #e1e9eb;border-radius:9px}.rating-head{display:flex;align-items:center;justify-content:space-between;gap:15px}.rating-head label{grid-template-columns:auto 150px;align-items:center}select,input[type=number]{padding:8px;border:1px solid #ccd9de;border-radius:7px;background:#fff}.evaluation small{color:#718089}.limitations,.experiment,.peer-review,.reconciliation{display:grid;gap:12px;padding:16px;border:1px solid #dbe5e8;border-radius:9px;background:#f8fbfb}.limitations h3,.limitations p,.experiment h3,.experiment h4,.experiment p,.peer-review h3,.peer-review h4,.peer-review p{margin:0}.limitations .remove,.peer-review .remove{justify-self:end;border:0;background:transparent;color:#a44035;font-weight:800}.experiment details{padding:10px;border-radius:7px;background:#fff}.experiment summary{cursor:pointer;font-weight:800}.experiment details p,.experiment details h4{margin-top:9px}.add-peer{display:grid;grid-template-columns:1fr auto;align-items:end;gap:10px}.peer-dimension{display:grid;gap:8px;padding:10px;border-left:3px solid #cfe1e2}.agreement{display:flex;justify-content:space-between;gap:12px;padding:12px;border-radius:8px;background:#eef7f4}.agreement span{color:#66767e}.reference-grid,.counts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.counts{grid-template-columns:repeat(4,minmax(0,1fr))}.sections{display:grid;gap:14px}.sections article{display:grid;gap:8px}label{display:grid;gap:7px;color:#41535b;font-size:12px;font-weight:800}textarea{box-sizing:border-box;width:100%;padding:12px;border:1px solid #ccd9de;border-radius:8px;font:inherit;line-height:1.45}textarea[readonly],input[readonly]{background:#f5f7f8;color:#46575f}.sections small{color:#718089}.conclusion{margin-top:18px}.conclusion p{margin-bottom:0;font-size:12px}.confirmation{grid-template-columns:auto 1fr;align-items:start;margin:20px 0;padding:16px;border-radius:9px;background:#eef7f4}.confirmation input{margin-top:2px}.notice{padding:13px;border-left:3px solid #2c718f;background:#f3f8fa}.error{padding:12px;border-radius:8px;background:#fff0ee;color:#a44035}.save-error{display:flex;justify-content:space-between}.save-error button{border:0;background:transparent;color:#8f352c;font-weight:800}footer{position:sticky;bottom:0;display:flex;align-items:center;justify-content:space-between;gap:18px;padding:15px 18px;border:1px solid #d4e1e3;border-radius:10px;background:#fff;box-shadow:0 10px 35px #193b4718}footer span{color:#66767e;font-size:12px}.export{display:flex;align-items:center;gap:14px;margin-top:20px}.export span{color:#66767e;font-size:12px}button:disabled{opacity:.45}.state{text-align:center;padding:35px;color:#66767e}@media(max-width:750px){.counts{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.page{padding:24px 14px 80px}header,footer,.export,.manual-actions,.rating-head{align-items:stretch;flex-direction:column}.add-peer,.reference-grid,.counts{grid-template-columns:1fr}.secondary{margin-left:0!important}}`]
})
export class PersonalAssessmentReportComponent implements OnDestroy {
  private readonly service=inject(PersonalAssessmentService); private readonly route=inject(ActivatedRoute); private readonly time=new ActiveTimeTracker();
  readonly id=this.route.snapshot.paramMap.get('id')||''; private readonly saves=new Subject<SaveRequest>(); private readonly subscription:Subscription;
  private revision=0; private approvalKey=crypto.randomUUID(); private readonly timingInterval=window.setInterval(()=>this.time.tick(),1000); private readonly onVisibility=()=>this.time.visibilityChanged();
  readonly assessment=signal<PersonalAssessmentSummary|null>(null); readonly collection=signal<PersonalAssessmentCollection|null>(null); readonly report=signal<PersonalAssessmentReport|null>(null); readonly draft=signal<ReportDraft|null>(null);
  readonly study=signal<AssessmentStudy|null>(null); readonly manualReport=signal<ManualReport>(this.emptyManual()); readonly manualDirty=signal(false);
  readonly limitationAnalysis=signal<AcademicLimitationAnalysis>(this.emptyLimitationAnalysis()); readonly limitationDirty=signal(false);
  readonly peerEvaluations=signal<AcademicPeerEvaluation[]>([]); readonly peerReviewerCode=signal(''); readonly peerDirtyIds=signal<Set<string>>(new Set()); readonly agreement=signal<AcademicAgreement|null>(null);
  readonly reconciliation=signal<AcademicEvaluationReconciliation>(this.emptyReconciliation()); readonly reconciliationDirty=signal(false);
  readonly generationExecutions=signal<ReportGenerationExecution[]>([]); readonly regenerationReason=signal(''); readonly regenerationLimitationId=signal(''); private regenerationKey=crypto.randomUUID();
  readonly evaluation=signal<AcademicReportEvaluation>(this.emptyEvaluation()); readonly evaluationDirty=signal(false);
  readonly humanConclusion=signal(''); readonly reviewConfirmed=signal(false); readonly loading=signal(true); readonly loadError=signal(''); readonly actionError=signal(''); readonly saveError=signal(''); readonly dirty=signal(false); readonly pending=signal(false); readonly working=signal(false);
  readonly sectionDefinitions:{key:SectionKey;label:string}[]=[{key:'context',label:'Contexto da avaliação'},{key:'observedKnowledge',label:'Conhecimentos observados'},{key:'strengths',label:'Pontos positivos'},{key:'concerns',label:'Pontos de atenção'},{key:'synthesis',label:'Síntese da minuta'}];
  readonly manualDefinitions:{key:keyof ManualReport;label:string}[]=[...this.sectionDefinitions,{key:'conclusion',label:'Conclusão do entrevistador'}];
  readonly dimensionDefinitions:{key:AcademicDimension;label:string;scale:string}[]=[
    {key:'PRESENCE',label:'Presença',scale:'0 ausente · 1 parcial · 2 informações esperadas presentes'},
    {key:'CORRESPONDENCE',label:'Correspondência',scale:'0 contradiz · 1 relação ambígua · 2 corresponde aos registros'},
    {key:'SUPPORT',label:'Sustentação',scale:'0 sem apoio · 1 apoio insuficiente · 2 afirmações apoiadas'},
    {key:'INSUFFICIENCY_HANDLING',label:'Tratamento da insuficiência',scale:'0 inventa/oculta · 1 sinaliza parcialmente · 2 explicita lacunas'},
    {key:'DECISION_SEPARATION',label:'Separação da decisão',scale:'0 decide · 1 linguagem ambígua · 2 preserva a decisão humana'},
  ];
  readonly limitationCategories:{key:AcademicLimitationCategory;label:string}[]=[{key:'INPUT',label:'Entrada'},{key:'CONTEXT',label:'Contexto'},{key:'PROMPT',label:'Prompt'},{key:'MODEL',label:'Modelo'},{key:'INTERFACE',label:'Interface'},{key:'HUMAN_REVIEW',label:'Revisão humana'}];
  constructor(){document.addEventListener('visibilitychange',this.onVisibility);this.subscription=this.saves.pipe(debounceTime(500),concatMap(request=>{this.pending.set(true);this.saveError.set('');return this.service.saveReport(this.id,this.report()!.version,request.draft,request.conclusion,request.confirmed,request.reviewActiveMillis).pipe(tap(saved=>{if(request.revision===this.revision){this.applyReport(saved);this.dirty.set(false)}else{this.report.set({...saved,draft:this.draft()!,humanConclusion:this.humanConclusion(),reviewConfirmed:this.reviewConfirmed()})}}),catchError(error=>{this.dirty.set(true);this.saveError.set(error.status===409?'A minuta mudou em outra sessão. Recarregue antes de continuar.':'Falha ao salvar. Suas alterações continuam nesta tela.');return EMPTY}),finalize(()=>this.pending.set(false)))})).subscribe();this.load();}
  ngOnDestroy(){this.subscription.unsubscribe();this.saves.complete();window.clearInterval(this.timingInterval);document.removeEventListener('visibilitychange',this.onVisibility)}
  readOnly(){return this.report()?.status==='APPROVED'}
  saveLabel(){return this.saveError()?'Falha ao salvar':this.pending()?'Salvando…':this.dirty()?'Alterações pendentes':'Salvo'}
  updateSection(key:SectionKey,text:string){const current=this.draft();if(!current||this.readOnly())return;this.change({...current,[key]:{...current[key],text}})}
  updateConclusion(value:string){if(this.readOnly())return;this.humanConclusion.set(value);this.queueSave()}
  updateConfirmation(value:boolean){if(this.readOnly())return;this.reviewConfirmed.set(value);this.queueSave()}
  retrySave(){const current=this.draft();if(current)this.saves.next({revision:this.revision,draft:current,conclusion:this.humanConclusion(),confirmed:this.reviewConfirmed(),reviewActiveMillis:this.reviewActiveMillis()})}
  generate(){const assessment=this.assessment(),collection=this.collection(),study=this.study();if(!assessment||!collection?.generationEligible||this.working()||(study&&!study.finalized))return;this.working.set(true);this.actionError.set('');this.service.generateReport(this.id,assessment.version).subscribe({next:value=>{this.applyReport(value);this.working.set(false)},error:error=>{this.working.set(false);this.actionError.set(error.error?.detail||'Não foi possível gerar a minuta com o Ollama local. Seus registros foram preservados.')}})}
  startStudy(){this.saveManual(true)}
  updateManual(key:keyof ManualReport,value:string){if(this.study()?.finalized)return;this.manualReport.set({...this.manualReport(),[key]:value});this.manualDirty.set(true)}
  manualComplete(){return Object.values(this.manualReport()).every(value=>value.trim().length>0)}
  saveManual(start=false){const assessment=this.assessment();if(!assessment||this.working()||(!start&&!this.manualDirty()))return;this.working.set(true);this.actionError.set('');this.service.saveManualReport(this.id,assessment.version,this.study()?.version||0,this.manualReport(),this.manualActiveMillis()).subscribe({next:value=>{this.applyStudy(value);this.manualDirty.set(false);this.working.set(false)},error:error=>{this.working.set(false);this.actionError.set(error.error?.detail||'Não foi possível salvar o parecer manual.')}})}
  finalizeManual(){const current=this.study();if(!current||this.manualDirty()||!this.manualComplete()||this.working())return;this.working.set(true);this.actionError.set('');this.service.finalizeManualReport(this.id,current.version,this.manualActiveMillis()).subscribe({next:value=>{this.applyStudy(value);this.working.set(false)},error:error=>{this.working.set(false);this.actionError.set(error.error?.detail||'Não foi possível finalizar o parecer manual.')}})}
  beginTiming(phase:TimingPhase,event:FocusEvent){if(!this.study()||(phase==='REVIEW'&&this.readOnly())||!this.timingControl(event.target))return;this.time.begin(phase)}
  activityTiming(phase:TimingPhase,event:Event){if(!this.study()||(phase==='REVIEW'&&this.readOnly())||!this.timingControl(event.target))return;this.time.activity(phase)}
  endTiming(phase:TimingPhase,event:FocusEvent){const section=event.currentTarget as HTMLElement,target=event.relatedTarget as Node|null;if(target&&section.contains(target)&&this.timingControl(target))return;this.time.end(phase)}
  manualActiveMillis(){return this.time.total('MANUAL')}
  reviewActiveMillis(){return this.time.total('REVIEW')}
  formatDuration(millis:number){const seconds=Math.floor(millis/1000);return `${Math.floor(seconds/60)}min ${seconds%60}s`}
  updateRating(index:number,key:'score'|'justification',value:number|string|null){if(this.study()?.evaluationFinalized)return;const dimensions=[...this.evaluation().dimensions];dimensions[index]={...dimensions[index],[key]:value};this.evaluation.set({...this.evaluation(),dimensions});this.evaluationDirty.set(true)}
  updateReferences(index:number,key:'sourceReferences'|'draftReferences',value:string){if(this.study()?.evaluationFinalized)return;const dimensions=[...this.evaluation().dimensions];dimensions[index]={...dimensions[index],[key]:value.split(/\r?\n/).map(item=>item.trim()).filter(Boolean)};this.evaluation.set({...this.evaluation(),dimensions});this.evaluationDirty.set(true)}
  updateCount(key:'expectedInformationMissing'|'factualClaimsAnalyzed'|'unsupportedClaims'|'revisedSections',value:number|null){if(this.study()?.evaluationFinalized)return;this.evaluation.set({...this.evaluation(),[key]:Math.max(0,Number(value)||0)});this.evaluationDirty.set(true)}
  joinReferences(values:string[]){return values.join('\n')}
  evaluationComplete(){return this.evaluationValueComplete(this.evaluation())}
  saveEvaluation(){const current=this.study();if(!current||current.evaluationFinalized||!this.evaluationDirty()||this.working())return;this.working.set(true);this.actionError.set('');this.service.saveStudyEvaluation(this.id,current.version,this.evaluation()).subscribe({next:value=>{this.applyStudy(value);this.evaluationDirty.set(false);this.working.set(false)},error:error=>{this.working.set(false);this.actionError.set(error.error?.detail||'Não foi possível salvar a ficha de avaliação.')}})}
  finalizeEvaluation(){const current=this.study();if(!current||current.evaluationFinalized||this.evaluationDirty()||!this.evaluationComplete()||this.working())return;this.working.set(true);this.actionError.set('');this.service.finalizeStudyEvaluation(this.id,current.version).subscribe({next:value=>{this.applyStudy(value);this.working.set(false)},error:error=>{this.working.set(false);this.actionError.set(error.error?.detail||'Não foi possível finalizar a ficha de avaliação.')}})}
  createPeerEvaluation(){const code=this.peerReviewerCode().trim();if(code.length<2||this.working()||this.study()?.reconciliation)return;this.working.set(true);this.actionError.set('');this.service.createPeerEvaluation(this.id,code).subscribe({next:value=>{this.peerEvaluations.update(items=>[...items,value]);this.peerReviewerCode.set('');this.working.set(false)},error:error=>{this.working.set(false);this.actionError.set(error.error?.detail||'Não foi possível criar a avaliação independente.')}})}
  updatePeerRating(peerIndex:number,dimensionIndex:number,key:'score'|'justification',value:number|string|null){const peer=this.peerEvaluations()[peerIndex];if(!peer||peer.finalized)return;const dimensions=[...peer.evaluation.dimensions];dimensions[dimensionIndex]={...dimensions[dimensionIndex],[key]:value};this.replacePeer(peerIndex,{...peer,evaluation:{...peer.evaluation,dimensions}});this.markPeerDirty(peer.id)}
  updatePeerReferences(peerIndex:number,dimensionIndex:number,key:'sourceReferences'|'draftReferences',value:string){const peer=this.peerEvaluations()[peerIndex];if(!peer||peer.finalized)return;const dimensions=[...peer.evaluation.dimensions];dimensions[dimensionIndex]={...dimensions[dimensionIndex],[key]:value.split(/\r?\n/).map(item=>item.trim()).filter(Boolean)};this.replacePeer(peerIndex,{...peer,evaluation:{...peer.evaluation,dimensions}});this.markPeerDirty(peer.id)}
  updatePeerCount(peerIndex:number,key:'expectedInformationMissing'|'factualClaimsAnalyzed'|'unsupportedClaims'|'revisedSections',value:number|null){const peer=this.peerEvaluations()[peerIndex];if(!peer||peer.finalized)return;this.replacePeer(peerIndex,{...peer,evaluation:{...peer.evaluation,[key]:Math.max(0,Number(value)||0)}});this.markPeerDirty(peer.id)}
  peerComplete(peer:AcademicPeerEvaluation){return this.evaluationValueComplete(peer.evaluation)}
  peerDirty(peerId:string){return this.peerDirtyIds().has(peerId)}
  savePeerEvaluation(peer:AcademicPeerEvaluation){if(peer.finalized||!this.peerDirty(peer.id)||this.working())return;this.working.set(true);this.actionError.set('');this.service.savePeerEvaluation(this.id,peer.id,peer.version,peer.evaluation).subscribe({next:value=>{this.updatePeer(value);this.clearPeerDirty(peer.id);this.working.set(false)},error:error=>{this.working.set(false);this.actionError.set(error.error?.detail||'Não foi possível salvar a avaliação independente.')}})}
  finalizePeerEvaluation(peer:AcademicPeerEvaluation){if(peer.finalized||this.peerDirty(peer.id)||!this.peerComplete(peer)||this.working())return;this.working.set(true);this.actionError.set('');this.service.finalizePeerEvaluation(this.id,peer.id,peer.version).subscribe({next:value=>{this.updatePeer(value);this.loadAgreement();this.working.set(false)},error:error=>{this.working.set(false);this.actionError.set(error.error?.detail||'Não foi possível finalizar a avaliação independente.')}})}
  deletePeerEvaluation(peer:AcademicPeerEvaluation){if(peer.finalized||this.working())return;this.working.set(true);this.actionError.set('');this.service.deletePeerEvaluation(this.id,peer.id).subscribe({next:()=>{this.peerEvaluations.update(items=>items.filter(item=>item.id!==peer.id));this.clearPeerDirty(peer.id);this.loadAgreement();this.working.set(false)},error:error=>{this.working.set(false);this.actionError.set(error.error?.detail||'Não foi possível remover a avaliação independente.')}})}
  finalizedPeerCount(){return this.peerEvaluations().filter(value=>value.finalized).length}
  peerSetReady(){const values=this.peerEvaluations();return values.length>0&&values.every(value=>value.finalized)}
  updateReconciliation(index:number,key:'agreedScore'|'rationale',value:number|string|null){if(this.study()?.reconciliationFinalized)return;const dimensions=[...this.reconciliation().dimensions];dimensions[index]={...dimensions[index],[key]:value};this.reconciliation.set({...this.reconciliation(),dimensions});this.reconciliationDirty.set(true)}
  updateReconciliationConclusion(value:string){if(this.study()?.reconciliationFinalized)return;this.reconciliation.set({...this.reconciliation(),overallConclusion:value});this.reconciliationDirty.set(true)}
  reconciliationComplete(){const value=this.reconciliation();return !!value.overallConclusion.trim()&&value.dimensions.length===this.dimensionDefinitions.length&&value.dimensions.every(item=>item.agreedScore!==null&&!!item.rationale.trim())}
  saveReconciliation(){const current=this.study();if(!current||current.reconciliationFinalized||!this.peerSetReady()||!this.reconciliationDirty()||this.working())return;this.working.set(true);this.actionError.set('');this.service.saveReconciliation(this.id,current.version,this.reconciliation()).subscribe({next:value=>{this.applyStudy(value);this.reconciliationDirty.set(false);this.working.set(false)},error:error=>{this.working.set(false);this.actionError.set(error.error?.detail||'Não foi possível salvar a conciliação.')}})}
  finalizeReconciliation(){const current=this.study();if(!current||current.reconciliationFinalized||this.reconciliationDirty()||!this.peerSetReady()||!this.reconciliationComplete()||this.working())return;this.working.set(true);this.actionError.set('');this.service.finalizeReconciliation(this.id,current.version).subscribe({next:value=>{this.applyStudy(value);this.working.set(false)},error:error=>{this.working.set(false);this.actionError.set(error.error?.detail||'Não foi possível finalizar a conciliação.')}})}
  addLimitation(){if(this.study()?.limitationAnalysisFinalized)return;this.limitationAnalysis.update(value=>({...value,findings:[...value.findings,{id:crypto.randomUUID(),category:'INPUT',description:'',sourceReferences:[],draftReferences:[],proposedAdjustment:'',expectedImpact:'',validationPlan:'',residualRisk:''}]}));this.limitationDirty.set(true)}
  removeLimitation(index:number){if(this.study()?.limitationAnalysisFinalized)return;this.limitationAnalysis.update(value=>({...value,findings:value.findings.filter((_,item)=>item!==index)}));this.limitationDirty.set(true)}
  updateLimitation(index:number,key:'category'|'description'|'proposedAdjustment'|'expectedImpact'|'validationPlan'|'residualRisk',value:string){if(this.study()?.limitationAnalysisFinalized)return;const findings=[...this.limitationAnalysis().findings];findings[index]={...findings[index],[key]:value};this.limitationAnalysis.set({...this.limitationAnalysis(),findings});this.limitationDirty.set(true)}
  updateLimitationReferences(index:number,key:'sourceReferences'|'draftReferences',value:string){if(this.study()?.limitationAnalysisFinalized)return;const findings=[...this.limitationAnalysis().findings];findings[index]={...findings[index],[key]:value.split(/\r?\n/).map(item=>item.trim()).filter(Boolean)};this.limitationAnalysis.set({...this.limitationAnalysis(),findings});this.limitationDirty.set(true)}
  updateLimitationConclusion(value:string){if(this.study()?.limitationAnalysisFinalized)return;this.limitationAnalysis.set({...this.limitationAnalysis(),overallConclusion:value});this.limitationDirty.set(true)}
  limitationAnalysisComplete(){const value=this.limitationAnalysis();return !!value.overallConclusion.trim()&&value.findings.length>0&&value.findings.every(item=>!!item.description.trim()&&item.sourceReferences.length>0&&item.draftReferences.length>0&&!!item.proposedAdjustment.trim()&&!!item.expectedImpact.trim()&&!!item.validationPlan.trim()&&!!item.residualRisk.trim())}
  saveLimitationAnalysis(){const current=this.study();if(!current||!current.evaluationFinalized||current.limitationAnalysisFinalized||!this.limitationDirty()||this.working())return;this.working.set(true);this.actionError.set('');this.service.saveLimitationAnalysis(this.id,current.version,this.limitationAnalysis()).subscribe({next:value=>{this.applyStudy(value);this.limitationDirty.set(false);this.working.set(false)},error:error=>{this.working.set(false);this.actionError.set(error.error?.detail||'Não foi possível salvar a análise de limitações.')}})}
  finalizeLimitationAnalysis(){const current=this.study();if(!current||current.limitationAnalysisFinalized||this.limitationDirty()||!this.limitationAnalysisComplete()||this.working())return;this.working.set(true);this.actionError.set('');this.service.finalizeLimitationAnalysis(this.id,current.version).subscribe({next:value=>{this.applyStudy(value);this.working.set(false)},error:error=>{this.working.set(false);this.actionError.set(error.error?.detail||'Não foi possível finalizar a análise de limitações.')}})}
  exportAcademicSummary(){if(this.working())return;this.working.set(true);this.actionError.set('');this.service.academicSummaryCsv().subscribe({next:value=>{const url=URL.createObjectURL(new Blob(['\uFEFF',value],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='resumo-estudo-minutas.csv';link.click();URL.revokeObjectURL(url);this.working.set(false)},error:()=>{this.working.set(false);this.actionError.set('Não foi possível exportar o resumo acadêmico.')}})}
  regenerateExperimental(){const reason=this.regenerationReason().trim(),limitationId=this.regenerationLimitationId();if(!this.study()?.limitationAnalysisFinalized||!limitationId||reason.length<10||this.working())return;this.working.set(true);this.actionError.set('');this.service.regenerateReport(this.id,limitationId,reason,this.regenerationKey).subscribe({next:value=>{this.generationExecutions.update(items=>items.some(item=>item.id===value.id)?items:[...items,value]);this.regenerationReason.set('');this.regenerationLimitationId.set('');this.regenerationKey=crypto.randomUUID();this.working.set(false)},error:error=>{this.working.set(false);this.actionError.set(error.error?.detail||'Não foi possível criar a execução experimental. A minuta original foi preservada.')}})}
  canApprove(){return !!this.report()&&!this.readOnly()&&!this.dirty()&&!this.pending()&&!this.saveError()&&!this.working()&&this.reviewConfirmed()&&!!this.humanConclusion().trim()}
  approve(){const current=this.report();if(!current||!this.canApprove())return;this.working.set(true);this.actionError.set('');this.service.approveReport(this.id,current.version,this.approvalKey,this.reviewActiveMillis()).subscribe({next:value=>{this.applyReport(value);this.working.set(false)},error:error=>{this.working.set(false);this.actionError.set(error.error?.detail||'Não foi possível aprovar o parecer.')}})}
  async exportPdf(download=true){const current=this.report(),assessment=this.assessment(),draft=this.draft();if(current?.status!=='APPROVED'||!assessment||!draft)return null;const {jsPDF}=await import('jspdf');const pdf=new jsPDF({unit:'mm',format:'a4'});const margin=18,maxWidth=174;let y=20;const page=()=>{pdf.addPage();y=20};const ensure=(height:number)=>{if(y+height>280)page()};const write=(text:string)=>{const lines=pdf.splitTextToSize(text,maxWidth) as string[];for(const line of lines){if(y+5>280)page();pdf.text(line,margin,y);y+=5}y+=5};pdf.setFont('helvetica','bold');pdf.setFontSize(16);pdf.text('Parecer técnico de avaliação',margin,y);y+=9;pdf.setFontSize(10);pdf.setFont('helvetica','normal');write(`Avaliação: ${assessment.title}\nPessoa avaliada: ${assessment.personName}\nAprovado em: ${new Date(current.approvedAt||current.updatedAt).toLocaleString('pt-BR')}`);for(const section of this.sectionDefinitions){ensure(12);pdf.setFont('helvetica','bold');pdf.setFontSize(12);pdf.text(section.label,margin,y);y+=6;pdf.setFont('helvetica','normal');pdf.setFontSize(10);write(draft[section.key].text)}ensure(12);pdf.setFont('helvetica','bold');pdf.setFontSize(12);pdf.text('Conclusão do entrevistador',margin,y);y+=6;pdf.setFont('helvetica','normal');pdf.setFontSize(10);write(this.humanConclusion());const pages=pdf.getNumberOfPages();for(let index=1;index<=pages;index++){pdf.setPage(index);pdf.setFontSize(8);pdf.setTextColor(110);pdf.text(`Página ${index} de ${pages}`,105,290,{align:'center'})}if(download){const name=assessment.personName.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'avaliacao';pdf.save(`parecer-tecnico-${name}.pdf`)}return pdf}
  private load(){forkJoin({assessment:this.service.get(this.id),collection:this.service.collection(this.id)}).subscribe({next:value=>{this.assessment.set(value.assessment);this.collection.set(value.collection);forkJoin({report:this.service.report(this.id).pipe(catchError(error=>error.status===404?of(null):throwError(()=>error))),study:this.service.study(this.id).pipe(catchError(error=>error.status===404?of(null):throwError(()=>error)))}).subscribe({next:loaded=>{if(loaded.report){this.applyReport(loaded.report);this.loadGenerations()}if(loaded.study)this.applyStudy(loaded.study);this.loading.set(false)},error:()=>{this.loading.set(false);this.loadError.set('Não foi possível carregar os artefatos desta avaliação.')}})},error:()=>{this.loading.set(false);this.loadError.set('Não foi possível carregar esta avaliação.')}})}
  private loadGenerations(){this.service.reportGenerations(this.id).subscribe({next:value=>this.generationExecutions.set(value),error:()=>this.actionError.set('Não foi possível carregar o histórico de gerações.')})}
  private change(draft:ReportDraft){this.draft.set(draft);this.queueSave()}
  private queueSave(){const draft=this.draft();if(!draft)return;this.dirty.set(true);this.saveError.set('');this.saves.next({revision:++this.revision,draft,conclusion:this.humanConclusion(),confirmed:this.reviewConfirmed(),reviewActiveMillis:this.reviewActiveMillis()})}
  private applyReport(value:PersonalAssessmentReport){this.report.set(value);this.draft.set(structuredClone(value.draft));this.humanConclusion.set(value.humanConclusion||'');this.reviewConfirmed.set(value.reviewConfirmed);this.time.hydrate('REVIEW',value.reviewActiveMillis)}
  private applyStudy(value:AssessmentStudy){this.study.set(value);this.manualReport.set(structuredClone(value.manualReport));this.evaluation.set(value.evaluation?structuredClone(value.evaluation):this.emptyEvaluation());this.limitationAnalysis.set(value.limitationAnalysis?structuredClone(value.limitationAnalysis):this.emptyLimitationAnalysis());this.reconciliation.set(value.reconciliation?structuredClone(value.reconciliation):this.emptyReconciliation());this.time.hydrate('MANUAL',value.manualActiveMillis);if(value.evaluationFinalized&&this.peerDirtyIds().size===0)this.loadPeerEvaluations()}
  private loadPeerEvaluations(){this.service.peerEvaluations(this.id).subscribe({next:values=>{this.peerEvaluations.set(values);this.loadAgreement()},error:()=>this.actionError.set('Não foi possível carregar as avaliações independentes.')})}
  private loadAgreement(){this.service.academicAgreement(this.id).subscribe({next:value=>this.agreement.set(value),error:()=>this.actionError.set('Não foi possível calcular a concordância entre avaliadores.')})}
  private replacePeer(index:number,value:AcademicPeerEvaluation){this.peerEvaluations.update(items=>items.map((item,current)=>current===index?value:item))}
  private updatePeer(value:AcademicPeerEvaluation){this.peerEvaluations.update(items=>items.map(item=>item.id===value.id?value:item))}
  private markPeerDirty(id:string){this.peerDirtyIds.update(ids=>new Set(ids).add(id))}
  private clearPeerDirty(id:string){this.peerDirtyIds.update(ids=>{const next=new Set(ids);next.delete(id);return next})}
  private evaluationValueComplete(value:AcademicReportEvaluation){return value.unsupportedClaims<=value.factualClaimsAnalyzed&&value.dimensions.length===this.dimensionDefinitions.length&&value.dimensions.every(item=>item.score!==null&&!!item.justification?.trim()&&(item.sourceReferences?.length||0)>0&&(item.draftReferences?.length||0)>0)}
  private timingControl(value:EventTarget|null){return value instanceof HTMLElement&&value.matches('textarea:not([readonly]),input:not([readonly]):not([disabled]),select:not([disabled]),[contenteditable="true"]')}
  private emptyManual():ManualReport{return{context:'',observedKnowledge:'',strengths:'',concerns:'',synthesis:'',conclusion:''}}
  private emptyEvaluation():AcademicReportEvaluation{return{dimensions:(['PRESENCE','CORRESPONDENCE','SUPPORT','INSUFFICIENCY_HANDLING','DECISION_SEPARATION'] as AcademicDimension[]).map(dimension=>({dimension,score:null,justification:'',sourceReferences:[],draftReferences:[]})),expectedInformationMissing:0,factualClaimsAnalyzed:0,unsupportedClaims:0,revisedSections:0}}
  private emptyLimitationAnalysis():AcademicLimitationAnalysis{return{findings:[],overallConclusion:''}}
  private emptyReconciliation():AcademicEvaluationReconciliation{return{dimensions:(['PRESENCE','CORRESPONDENCE','SUPPORT','INSUFFICIENCY_HANDLING','DECISION_SEPARATION'] as AcademicDimension[]).map(dimension=>({dimension,agreedScore:null,rationale:''})),overallConclusion:''}}
}
